using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class SharkDolphinReview {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity";
 [Serializable] public class Motion {public string kind,name;public float tailSide,tailVertical,headMotion,flukeMismatch,loopSeam,travel,stoppedFraction,maxTurn,minPodGap;}
 [Serializable] public class Report {public Motion[] animals;}
 static SeaLife[] Animals()=>UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(l=>l.kind=="Dolphin"||l.kind=="Reef shark").OrderBy(l=>l.name).ToArray();
 public static void Inspect(){EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var animals=Animals();var rows=new List<Motion>();foreach(var a in animals){var animation=a.GetComponentInChildren<Animation>();var skin=a.GetComponentsInChildren<SkinnedMeshRenderer>().First(r=>r.enabled);var clip=animation.clip;clip.SampleAnimation(animation.gameObject,0);var initial=OctopusRepairValidation.Points(skin).Select(p=>a.transform.InverseTransformPoint(p)).ToArray();float zmin=initial.Min(p=>p.z),zmax=initial.Max(p=>p.z),length=zmax-zmin;var tail=Enumerable.Range(0,initial.Length).Where(i=>initial[i].z<zmin+length*.12f).ToArray();var head=Enumerable.Range(0,initial.Length).Where(i=>initial[i].z>zmax-length*.15f).ToArray();float xcenter=tail.Average(i=>initial[i].x);var left=tail.Where(i=>initial[i].x<xcenter).ToArray();var right=tail.Where(i=>initial[i].x>=xcenter).ToArray();var positions=new List<Vector3>();float mismatch=0,headMove=0,seam=0;Vector3 head0=head.Aggregate(Vector3.zero,(v,i)=>v+initial[i])/head.Length;float tilt0=left.Average(i=>initial[i].y)-right.Average(i=>initial[i].y);
 for(int f=0;f<=60;f++){clip.SampleAnimation(animation.gameObject,clip.length*f/60);var p=OctopusRepairValidation.Points(skin).Select(v=>a.transform.InverseTransformPoint(v)).ToArray();positions.Add(tail.Aggregate(Vector3.zero,(v,i)=>v+p[i])/tail.Length);headMove=Mathf.Max(headMove,Vector3.Distance(head0,head.Aggregate(Vector3.zero,(v,i)=>v+p[i])/head.Length));mismatch=Mathf.Max(mismatch,Mathf.Abs(left.Average(i=>p[i].y)-right.Average(i=>p[i].y)-tilt0));if(f==60)for(int i=0;i<p.Length;i++)seam=Mathf.Max(seam,Vector3.Distance(p[i],initial[i]));}
 clip.SampleAnimation(animation.gameObject,0);rows.Add(new Motion{kind=a.kind,name=a.name,tailSide=positions.Max(p=>p.x)-positions.Min(p=>p.x),tailVertical=positions.Max(p=>p.y)-positions.Min(p=>p.y),headMotion=headMove,flukeMismatch=mismatch,loopSeam=seam,minPodGap=1000});}
 const float dt=1f/30;int frames=3600;var stopped=new int[animals.Length];for(int f=0;f<frames;f++)for(int i=0;i<animals.Length;i++){var a=animals[i];var before=a.transform.position;var forward=a.transform.forward;if(a.kind=="Dolphin")a.GetComponent<WreckCreature>().Step(dt,OceanWorld.Centers[2]+Vector3.up*1.6f);else a.GetComponent<OpenWaterShark>().Step(dt,OceanWorld.Centers[6],Vector3.zero,true);a.GetComponent<ReefAnimalClearance>().Enforce();float moved=Vector3.Distance(before,a.transform.position);rows[i].travel+=moved;if(moved<.05f*dt)stopped[i]++;rows[i].maxTurn=Mathf.Max(rows[i].maxTurn,Vector3.Angle(forward,a.transform.forward)/dt);if(a.kind=="Dolphin")foreach(var other in animals.Where(b=>b!=a&&b.kind=="Dolphin"))rows[i].minPodGap=Mathf.Min(rows[i].minPodGap,Vector3.Distance(a.transform.position,other.transform.position));}for(int i=0;i<rows.Count;i++){rows[i].stoppedFraction=(float)stopped[i]/frames;Debug.Log("SWIM_REVIEW "+JsonUtility.ToJson(rows[i]));}Directory.CreateDirectory("Renders/SharkDolphinReview");File.WriteAllText("Renders/SharkDolphinReview/motion.json",JsonUtility.ToJson(new Report{animals=rows.ToArray()},true));}
 public static void Install(){AssetDatabase.Refresh();var clip=(AnimationClip)typeof(MarineModelRefresh).GetMethod("Import",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{"Dolphin"});var scene=EditorSceneManager.OpenScene(Scene);var diver=UnityEngine.Object.FindFirstObjectByType<Diver>();var rig=diver.transform.position;var head=diver.transform.Find("Head");var headPose=head.localToWorldMatrix;
 foreach(var a in Animals().Where(a=>a.kind=="Dolphin")){var player=a.GetComponentInChildren<Animation>();var serialized=new SerializedObject(player);serialized.FindProperty("m_Animation").objectReferenceValue=clip;var entries=serialized.FindProperty("m_Animations");entries.arraySize=1;entries.GetArrayElementAtIndex(0).objectReferenceValue=clip;serialized.ApplyModifiedPropertiesWithoutUndo();player.playAutomatically=true;player.cullingType=AnimationCullingType.AlwaysAnimate;typeof(MarineModelRefresh).GetMethod("Envelopes",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{player.gameObject,clip});var guard=a.GetComponent<ReefAnimalClearance>();guard.animatedBody=AnimalSeabedRepair.Envelope(a.transform);guard.Enforce();EditorUtility.SetDirty(guard);}
 if(diver.transform.position!=rig||head.localToWorldMatrix!=headPose)throw new Exception("Changed diver start");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Inspect();MarineModelRefresh.Regression();Debug.Log("SHARK_DOLPHIN_SWIM_UPDATE_VALIDATED diverStartPreserved=true");}
}}